sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var requestBody = request.body.data;

    if (!requestBody || !requestBody.update_set_name) {
        return response.setStatus(400).setBody({ error: "Missing 'update_set_name' parameter in the request body" });
    }

    var updateSetNames = Array.isArray(requestBody.update_set_name) ? requestBody.update_set_name : [requestBody.update_set_name];
    var results = [];

    updateSetNames.forEach(function(updateSetName) {
        var remoteUpdatesetId = "6b2ea2e4838ed2109a4b66d0deaad303";

        var gr = new GlideRecord('sys_remote_update_set');
        gr.addQuery('name', updateSetName);
        gr.query();

        if (gr.next()) {
            gs.log('update set checking');
            remoteUpdatesetId = gr.getUniqueValue();

            var remoteUpdateset = new GlideRecord('sys_remote_update_set');
            remoteUpdateset.addQuery('sys_id', remoteUpdatesetId);
            remoteUpdateset.query();

            if (remoteUpdateset.next()) {
                var worker = new GlideUpdateSetWorker();
                var lus = new GlideRecord('sys_update_set');
                if (!lus.canWrite()) {
                    results.push({ updateSetName, error: "Permission denied to create update sets" });
                    return;
                }

                var lusSysId = worker.remoteUpdateSetCommit(lus, remoteUpdateset, remoteUpdateset.update_source.url);
                _copyUpdateXML(lusSysId, remoteUpdateset.sys_id);
                remoteUpdateset.update();

                worker.setUpdateSetSysId(lusSysId);
                worker.setProgressName(gs.getMessage("Committing update set: {0}", remoteUpdateset.name));
                worker.setBackground(true);
                worker.start();

                results.push({
                    updateSetName,
                    success: true,
                    progressId: worker.getProgressID(),
                    updateSetId: lusSysId,
                    refreshNav: _shouldRefreshNav(remoteUpdatesetId),
                    refreshAppsList: _shouldRefreshAppsList(remoteUpdatesetId)
                });
            } else {
                results.push({ updateSetName, error: "Remote update set not found" });
            }
        } else {
            results.push({
                updateSetName,
                status: "error",
                message: "No update set found with the name: " + updateSetName
            });
        }
    });

    response.setBody(results);

    function _copyUpdateXML(lsysid, rsysid) {
        var xgr = new GlideRecord("sys_update_xml");
        xgr.addQuery("remote_update_set", rsysid);
        xgr.query();
        while (xgr.next()) {
            var lxgr = new GlideRecord("sys_update_xml");
            lxgr.initialize();
            lxgr.name = xgr.name;
            lxgr.payload = xgr.payload;
            lxgr.action = xgr.action;
            lxgr.type = xgr.type;
            lxgr.target_name = xgr.target_name;
            lxgr.view = xgr.view;
            lxgr.update_domain = xgr.update_domain;
            lxgr.table = xgr.table;
            lxgr.category = xgr.category;
            lxgr.application = xgr.application;
            lxgr.update_set = lsysid;
            lxgr.insert();
        }
    }

    function _shouldRefreshNav(rsysid) {
        var xgr = new GlideRecord("sys_update_xml");
        xgr.addQuery("remote_update_set", rsysid);
        xgr.addQuery("type", ["Module", "Application Menu"]);
        xgr.query();
        return xgr.hasNext();
    }

    function _shouldRefreshAppsList(rsysid) {
        var xgr = new GlideRecord("sys_update_xml");
        xgr.addQuery("remote_update_set", rsysid);
        xgr.addQuery("type", "Application");
        xgr.query();
        return xgr.hasNext();
    }
})(request, response);
